def files_match(actual):
    assert len(actual) == len(set(actual)), "Duplicate scope file"
    assert set(actual) == set(EXPECTED) | {SELF}, "Unexpected or missing completion file"
def bytes_match(name, value):
    assert hashlib.sha256(value).hexdigest() == EXPECTED[name], "Completion content changed: " + name
def rejected(action):
    try: action()
    except AssertionError: return
    raise AssertionError("Negative scope assertion did not reject")
def main():
    os.chdir(Path(__file__).resolve().parents[1])
    git = lambda *args: subprocess.check_output(["git", *args], text=True).strip()
    branch = os.environ.get("GITHUB_HEAD_REF") or os.environ.get("GITHUB_REF_NAME")
    assert branch == "fix/enterprise-completion-20260919", "Unregistered branch"
    if os.environ.get("PR_NUMBER"): assert os.environ["PR_NUMBER"] == "1116", "Wrong PR"
    assert git("merge-base", BASE, "HEAD") == BASE, "Wrong base"
    assert git("merge-base", "origin/main", "HEAD") == BASE, "Main advanced; revalidate"
    files_match(git("diff", "--name-only", BASE).splitlines())
    for name in EXPECTED: bytes_match(name, Path(name).read_bytes())
    actual = list(EXPECTED) + [SELF]
    for name in actual: rejected(lambda: files_match([p for p in actual if p != name]))
    for name in ["database/migrations/unreviewed.sql", ".github/workflows/projectpulse-deploy-production.yml", "deployment/azure/unreviewed.sh"]:
        rejected(lambda: files_match(actual + [name]))
    for name in EXPECTED: rejected(lambda: bytes_match(name, Path(name).read_bytes() + b"changed"))
    assert git("diff", "--name-only", BASE, "--", "deployment", ".github/workflows/projectpulse-deploy-production.yml", ".github/flowhive-psa-protected-test-candidate.json") == "", "Deployment infrastructure, Production or candidate authority changed"
    subprocess.run(["git", "diff", "--check", BASE], check=True)
    print(f"ENTERPRISE_COMPLETION_EXACT_SCOPE=PASS files={len(actual)} production_and_candidate_authority=unchanged")
if __name__ == "__main__": main()
